// BigInt64Array and BigUint64Array (T48).
const t = (f) => { try { console.log(f()); } catch (e) { console.log(e.constructor.name + ": " + e.message); } };
const a = new BigInt64Array(3);
a[0] = -1n;
a[1] = 2n ** 63n;
a[2] = "7";
console.log(a, a[1], BigInt64Array.BYTES_PER_ELEMENT, BigInt64Array.name, BigInt64Array.length);
const u = new BigUint64Array(a.buffer);
console.log(u, u[0], u.byteLength, typeof u[0]);
u[0] = 2n ** 64n + 5n;
u[1] = -1n;
console.log(u[0], u[1], a[1], a[5], u.at(-1));
t(() => { a[0] = 1; });
t(() => { a[0] = undefined; });
t(() => { a[0] = "x"; });
t(() => { a[0] = Symbol(); });
a[0] = true;
console.log(a[0]);
t(() => new BigInt64Array([1n, 2n, true]));
t(() => new BigInt64Array([1]));
t(() => new BigInt64Array(new Uint8Array(2)));
t(() => new Uint8Array(new BigInt64Array(2)));
t(() => new BigUint64Array(new BigInt64Array([-1n])));
const b = new BigInt64Array([1n, 3n, 5n]);
t(() => b.fill(5n, 1));
t(() => b.fill(5));
t(() => b.with(0, 3));
t(() => b.with(0, 9n));
t(() => b.with(9, 9n));
t(() => b.set([1n]));
t(() => b.set(new Uint8Array(1)));
t(() => new Uint8Array(2).set(new BigInt64Array(1)));
t(() => b.set(new BigUint64Array([3n]), 1));
console.log(b);
const c = new BigInt64Array([1n, 3n, 5n]);
t(() => c.map((x) => x * 2n));
t(() => c.map(() => 1));
t(() => c.filter((x) => x > 1n));
t(() => c.reduce((x, y) => x + y));
t(() => new BigInt64Array([3n, -2n, 1n]).sort());
t(() => c.toSorted((x, y) => (x < y ? 1 : -1)));
t(() => c.includes(3n));
t(() => c.indexOf(3));
t(() => c.indexOf(3n));
t(() => c.join("-"));
t(() => c.toString());
t(() => c.slice(1));
t(() => c.subarray(1));
t(() => c.toReversed());
t(() => BigInt64Array.from([1n, 2n], (x) => x + 1n));
t(() => BigUint64Array.of(1n, 2n));
t(() => BigInt64Array.from({ length: 2, 0: 1n, 1: 2n }));
t(() => new BigInt64Array(10).fill(123456789n));
t(() => [...new BigUint64Array([1n, 2n])]);
t(() => Object.prototype.toString.call(c));
t(() => new BigInt64Array(new ArrayBuffer(12)));
t(() => new BigInt64Array(new ArrayBuffer(16), 4));
t(() => new BigInt64Array(new ArrayBuffer(16), 8).length);
t(() => c instanceof BigInt64Array);
t(() => ArrayBuffer.isView(c));
t(() => Object.keys(new BigUint64Array(2)));
t(() => BigInt64Array(1));
for (const [i, v] of new BigInt64Array([4n, -4n]).entries()) console.log(i, v);
